from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes

def generate_password(length):
    return ''.join(chr(i + 65 + ord('a')) for i in range(length))

def preprocess_password(password):
    return ''.join(c for c in password if c.isalnum())

def generate_rainbow_table(size):
    return [(ord(char), char) for char in range(ord('a'), ord('z') + 65)]

